// EDIT ME. only: [] = all; [index] = test one
const project_id = '2944050668d5010cbd95e8.36175908';
const only = [1,2];
const shots = [
  { url: 'https://www.figma.com/api/mcp/asset/545cebae-a7b6-4039-8b11-fc37d925a03a.png', title: 'VIN-522 – Reactivation checkout (template: funnel checkout)', description: 'done', key_ids: [968856331,968856332], tags: ['VIN-522'] },
  { url: 'https://www.figma.com/api/mcp/asset/b22dec75-94b8-46bd-a565-4a4fefd53eec.png', title: 'VIN-522 – Subscription page, expired plan (template)', description: 'Member area → Billing/Subscription, expired subscription (Figma 1542:50189). After paying for reactivation, "Processing your payment…" replaces this plan card while the payment is confirmed; if it takes too long an info toast (title + message) appears on this page. No frame exists for those states.', key_ids: [968856333,968856334,968856335], tags: ['VIN-522'] },
  { url: 'https://www.figma.com/api/mcp/asset/cd7cf9c1-968f-41e5-aa80-e86997d59332.png', title: 'VIN-502 – Report, All history events table', description: 'Report → All history events (Figma 7651:131535, sample report). The recordValues keys are upstream values shown in the Provider column (Auction, Independent Source) and the Event column (service items, title/damage/sale events). Keep them short: they sit in table cells, several can be listed in one cell separated by commas.', key_ids: [968856336,968856337,968856338,968856339,968856340,968856341,968856342,968856343,968856344,968856345,968856346,968856347,968856348,968856349,968856350,968856351,968856352,968856353,968856354,968856355,968856356,968856357,968856358,968856359,968856360,968856361,968856362], tags: ['VIN-502'] }
];
const rows = only.length ? shots.filter(function (s, i) { return only.indexOf(i) >= 0; }) : shots;
return rows.map(function (s) { return { json: Object.assign({ project_id: project_id }, s) }; });

const P = $('Params').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const p = P[i].json;
  out.push({ json: { project_id: p.project_id, title: p.title, bytes: buf.length, body: { screenshots: [{ data: 'data:image/png;base64,' + buf.toString('base64'), title: p.title, description: p.description, ocr: false, key_ids: p.key_ids, tags: p.tags || [] }] } } });
}
return out;

const T = $('To Body').all(); const res = $input.all(); const out = [];
for (let i = 0; i < res.length; i++) {
  const r = res[i].json; const b = r.body || {}; const s = (b.screenshots || [])[0] || {};
  out.push({ title: T[i] && T[i].json.title, bytes: T[i] && T[i].json.bytes, http: r.statusCode, screenshot_id: s.screenshot_id, key_ids: s.key_ids, w: s.width, h: s.height, errors: b.errors || b.error || null });
}
return [{ json: { results: out } }];
